-- Sample job listings for the AfterWorks marketplace.
-- Sample listings: employers are fictional, salaries are illustrative and these are not verified vacancies.
-- Generated from scripts/sample-jobs/*.ts — edit the source, not this file.

CREATE TABLE IF NOT EXISTS sample_job_listings (
  reference_id        VARCHAR(32)  NOT NULL PRIMARY KEY,
  title               VARCHAR(160) NOT NULL,
  company             VARCHAR(160) NOT NULL,
  country             VARCHAR(80)  NOT NULL,
  city                VARCHAR(80)  NOT NULL,
  region              ENUM('Europe','Africa','Asia','Americas') NOT NULL,
  description         TEXT         NOT NULL,
  salary_amount       DECIMAL(12,2) NOT NULL,
  salary_currency     CHAR(3)      NOT NULL,
  salary_frequency    ENUM('hourly','weekly','monthly') NOT NULL,
  salary_usd          DECIMAL(12,2) NOT NULL,
  employment_type     ENUM('Full-time','Part-time','Contract','Internship') NOT NULL,
  work_arrangement    ENUM('Remote','Hybrid','Onsite') NOT NULL,
  experience_level    ENUM('Entry-level','Intermediate','Experienced') NOT NULL,
  required_skills     VARCHAR(400) NOT NULL,
  education           VARCHAR(300) NOT NULL,
  application_deadline DATE        NOT NULL,
  applicants          INT UNSIGNED NOT NULL,
  application_requirements VARCHAR(600) NOT NULL,
  is_sample           TINYINT(1)   NOT NULL DEFAULT 1,
  INDEX idx_region (region),
  INDEX idx_country (country)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT IGNORE INTO sample_job_listings
  (reference_id, title, company, country, city, region, description, salary_amount, salary_currency,
   salary_frequency, salary_usd, employment_type, work_arrangement, experience_level, required_skills,
   education, application_deadline, applicants, application_requirements, is_sample)
VALUES
('SAMPLE-EU-001', 'Virtual Assistant', 'Nordwind Assist GmbH', 'Germany', 'Berlin', 'Europe', 'Support a two-partner consulting firm with inbox triage, calendar coordination and travel booking across three time zones. You will own the morning brief and keep client follow-ups from slipping between meetings.', 22, 'EUR', 'hourly', 23.8, 'Part-time', 'Remote', 'Entry-level', 'Calendar management, Written German and English, Google Workspace, Notion', 'Secondary school diploma; relevant certificates welcome', '2026-12-19', 84, 'CV (PDF, max 2 pages); Short cover note in German; Availability across CET business hours', 1),
('SAMPLE-EU-002', 'Data Entry Specialist', 'Thames Record Services Ltd', 'United Kingdom', 'Manchester', 'Europe', 'Transfer paper archive records into a structured compliance database, reconciling each entry against the scanned source. The backlog is roughly 12,000 records and accuracy is audited on a sample every week.', 14, 'GBP', 'hourly', 17.6, 'Contract', 'Hybrid', 'Entry-level', 'High-volume data entry, Excel, Attention to detail, OCR tools', 'GCSEs or equivalent', '2026-12-12', 132, 'CV; A 15-minute accuracy test; Right to work in the UK', 1),
